/// <summary>
/// Logic block containing the necessary business logic to create a movement journal
/// </summary>
class MwmsLogicBlockCreateMovementJournal extends MwmsLogicBlockjournalsCommon implements TFMLogicBlockDataCollectionInterface
{


}

Method.Source:
/// <summary>
/// This method provides the header fields, that are needed to find out which data should be collected.
/// </summary>
/// <returns>A TFMReferenceDataConfiguration object, containing registration collectors for the header.</returns>
public TFMReferenceDataConfiguration headerFieldsNeeded()
{
    TFMRegistrationCollectorList	journalList = new TFMRegistrationCollectorList(2,extendedTypeStr(JournalNameId),"@TFM:JournalName","@TFM:JournalName","@TFM:JournalName");
    refConf = components.getHeaders();
    journalList.parmDataTable(methodStr(MobDocMovementJournal,JournalNames));
    refConf.addCollector(journalList);

    return refConf;
}

public static MwmsLogicBlockCreateMovementJournal Construct()
{
    return new MwmsLogicBlockCreateMovementJournal();
}

protected void new()
{
    super();


    categories.add("@SYS547");
    components.addComponent(new MwmsLogicComponentInventoryJournalsCommonHeader());
}

public Set autoCreatedProcesses()
{
    Set ret = super();
    TFMProcess process = TFMProcess::Construct('CreateMovementJournal');
    process.addBlock(this);
    ret.add(process);
    return ret;
}

/// <summary>
/// Name of the block Type.
/// </summary>
/// <returns>Name of the block</returns>
public Name blockName()
{
    return "@MobileWMS:CreateMovementJournal";
}

/// <summary>
/// This method gives you the registration collectors for this data collection block.
/// </summary>
/// <returns>A collection of registration collectors.</returns>
public TFMRegistrationCollectors registrationCollectors()
{
    return components.getCollectors();
}

/// <summary>
/// This method is called before the post method, and gives the option to add extra registration collectors for the user to be prompted for before the post method is executed.
/// </summary>
/// <param name = "_request">The request object, containing all data collected so far.</param>
/// <returns>Returns a TFMRegistrationCollectors object if the user must be further prompted, otherwise it returns null</returns>
public TFMRegistrationCollectors prePostRegistrationCollectors()
{
    return null;
}

/// <summary>
/// The method executed when all data has been collected, and contains the posting logic.
/// </summary>
/// <returns>A TFMPostResponseData object.</returns>
public TFMPostResponseData post()
{

    TFMPostResponseData                 response = TFMPostResponseData::Construct();

    // Get the name of the profit/loss journal to create

    inventJournalTable.clear();
    inventJournalTable.JournalType          = inventJournalType::Movement;
    inventJournalTable = components.provideDataIfPossible(inventJournalTable);        
    inventJournalTable.insert();

    response.parmResponseText("@TaskletMobileWMS:MovementJournalCreatedsuccessful");


    return response;
}
